<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['error'=>'Method not allowed']);exit;}
$config=require __DIR__.'/../config/config.php';$body=json_decode(file_get_contents('php://input'),true)??[];$pid=(int)($body['product_id']??0);$email=trim((string)($body['email']??''));$customer=$body['customer']??[];
try{$pdo=new PDO("mysql:host={$config['db']['host']};port={$config['db']['port']};dbname={$config['db']['name']};charset={$config['db']['charset']}",$config['db']['user'],$config['db']['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1 LIMIT 1');$s->execute([$pid]);$p=$s->fetch();if(!$p){http_response_code(404);echo json_encode(['error'=>'Product unavailable']);exit;}$num='SMB-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$i=$pdo->prepare('INSERT INTO orders(order_number,product_id,customer_email,customer_data,amount,currency) VALUES(?,?,?,?,?,?)');$i->execute([$num,$pid,$email,json_encode($customer,JSON_UNESCAPED_UNICODE),$p['price'],$p['currency']]);echo json_encode(['order_number'=>$num,'maketou_cart_id'=>$p['maketou_cart_id']]);}catch(Throwable $e){http_response_code(500);echo json_encode(['error'=>'Unable to create order']);}
